/* From Uiverse.io by mrhyddenn - Tags: switch */
/* The switch - the box around the slider */
.__UIV_SCOPE__ .switch {
 font-size: 17px;
 position: relative;
 display: inline-block;
 width: 3.5em;
 height: 2em;
}

/* Hide default HTML checkbox */
.__UIV_SCOPE__ .switch input {
 opacity: 0;
 width: 0;
 height: 0;
}

/* The slider */
.__UIV_SCOPE__ .slider {
 position: absolute;
 cursor: pointer;
 top: 0;
 left: 0;
 right: 0;
 bottom: 0;
 background-color: #fff;
 border: 1px solid #99999;
 transition: .4s;
}

.__UIV_SCOPE__ .slider:before {
 position: absolute;
 content: "";
 height: 1.5em;
 width: 1.5em;
 left: 0.20em;
 bottom: 0.25em;
 background-color: white;
 transition: .4s;
 box-shadow: 0 0 2px 0px #999999;
}

.__UIV_SCOPE__ input:checked + .slider {
 background-color: #2da54f;
}

.__UIV_SCOPE__ input:focus + .slider {
 box-shadow: 0 0 1px #2196F3;
}

.__UIV_SCOPE__ input:checked + .slider:before {
 transform: translateX(1.5em);
}
